// Secure Express.js application with enhanced error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware setup
app.use(helmet()); // Sets various security headers
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded payload

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Basic XSS protection - strip script tags and dangerous characters
  const sanitize = (obj) => {
    if (typeof obj !== 'object' || obj === null) return obj;

    for (let key in obj) {
      if (typeof obj[key] === 'string') {
        // Remove potentially dangerous characters and script tags
        obj[key] = obj[key]
          .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
          .replace(/[<>]/g, '')
          .trim();
      } else if (typeof obj[key] === 'object') {
        sanitize(obj[key]);
      }
    }
  };

  if (req.body) sanitize(req.body);
  if (req.query) sanitize(req.query);
  if (req.params) sanitize(req.params);

  next();
};
app.use(sanitizeInput);

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({
      error: 'Internal Server Error',
      message: 'Something went wrong. Please try again later.'
    });
  }

  res.status(500).json({
    error: err.name,
    message: err.message,
    stack: err.stack
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found.'
  });
});

// Health endpoint with validation
app.get('/health', [
  // Validate query parameters if any
  body('detail').optional().isBoolean().withMessage('Detail must be a boolean')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation Error',
      details: errors.array()
    });
  }

  try {
    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    // Optional detail parameter
    if (req.query.detail === 'true') {
      response.memory = process.memoryUsage();
      response.env = process.env.NODE_ENV || 'development';
    }

    res.json(response);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Health check failed'
    });
  }
});

// Users endpoint with enhanced security
app.get('/users', [
  // Input validation
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation Error',
      details: errors.array()
    });
  }

  try {
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        role: 'user',
        createdAt: '2023-01-01T00:00:00.000Z'
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        role: 'user',
        createdAt: '2023-01-02T00:00:00.000Z'
      },
    ];

    // Apply filters safely
    const limit = parseInt(req.query.limit) || users.length;
    const page = parseInt(req.query.page) || 1;

    const paginatedUsers = users.slice(0, limit);

    // Sanitize output - don't expose unnecessary fields
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
    }));

    res.json({
      data: sanitizedUsers,
      pagination: {
        total: users.length,
        page,
        limit,
        hasMore: limit < users.length
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Failed to retrieve users'
    });
  }
});

// Handle uncaught exceptions and rejections
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

const request = require('supertest');
const app = require('../app-secure');

describe('Security and Error Handling Tests', () => {

  test('Health endpoint returns valid response', async () => {
    const response = await request(app).get('/health');
    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('status', 'ok');
    expect(response.body).toHaveProperty('timestamp');
  });

  test('Health endpoint with invalid parameter returns 400', async () => {
    const response = await request(app)
      .get('/health')
      .query({ detail: 'not-a-boolean' });

    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Validation Error');
  });

  test('Users endpoint returns sanitized data', async () => {
    const response = await request(app).get('/users');
    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('data');
    expect(response.body).toHaveProperty('pagination');

    // Check that sensitive fields are not exposed
    response.body.data.forEach(user => {
      expect(user).not.toHaveProperty('role');
      expect(user).not.toHaveProperty('createdAt');
    });
  });

  test('Users endpoint with XSS attempt is sanitized', async () => {
    const response = await request(app)
      .get('/users')
      .query({ limit: '<script>alert("xss")</script>' });

    // Should either reject or sanitize the input
    expect([200, 400]).toContain(response.status);
  });

  test('Non-existent endpoint returns 404', async () => {
    const response = await request(app).get('/nonexistent');
    expect(response.status).toBe(404);
    expect(response.body).toHaveProperty('error', 'Not Found');
  });

  test('Rate limiting is working', async () => {
    // Make multiple rapid requests
    const requests = Array(105).fill().map(() => 
      request(app).get('/health')
    );

    const responses = await Promise.all(requests);
    const rateLimited = responses.filter(r => r.status === 429);

    // Should have some rate-limited responses
    expect(rateLimited.length).toBeGreaterThan(0);
  });
});

