  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  const allowedParams = ['page', 'limit', 'sort'];
  const queryKeys = Object.keys(req.query);

  const invalidParams = queryKeys.filter(key => !allowedParams.includes(key));

  if (invalidParams.length > 0) {
    return res.status(400).json({
      error: 'Invalid query parameters',
      details: `The following parameters are not allowed: ${invalidParams.join(', ')}`
    });
  }

  // Validate parameter values
  if (req.query.page && !/^\d+$/.test(req.query.page)) {
    return res.status(400).json({
      error: 'Invalid parameter value',
      details: 'Page parameter must be a positive integer'
    });
  }

  if (req.query.limit && !/^\d+$/.test(req.query.limit)) {
    return res.status(400).json({
      error: 'Invalid parameter value',
      details: 'Limit parameter must be a positive integer'
    });
  }

  next();
};

// Error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't expose error details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({
      error: 'Internal server error',
      message: 'Something went wrong'
    });
  }

  res.status(500).json({
    error: 'Internal server error',
    message: error.message,
    stack: error.stack
  });
});

// Health endpoint with validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed'
    });
  }
});

// Users endpoint with proper input validation and error handling
app.get('/users', validateQueryParams, (req, res) => {
  try {
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const sort = req.query.sort || 'name';

    // Validate sort parameter
    const allowedSortFields = ['id', 'name', 'email'];
    if (!allowedSortFields.includes(sort)) {
      return res.status(400).json({
        error: 'Invalid sort parameter',
