  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
}));

// Users endpoint with validation
app.get('/users', asyncHandler(async (req, res) => {
  // Validate query parameters if needed
  const { limit, offset } = req.query;

  // Input validation example
  if (limit && (isNaN(limit) || parseInt(limit) > 100)) {
    return res.status(400).json({ 
      error: 'Invalid limit parameter. Must be a number <= 100' 
    });
  }

  // Simulate database call with error handling
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if parameters provided
    const result = users.slice(
      offset ? parseInt(offset) : 0,
      limit ? parseInt(offset || 0) + parseInt(limit) : users.length
    );

    res.json({
      data: result,
      total: users.length,
      limit: limit ? parseInt(limit) : null,
      offset: offset ? parseInt(offset) : 0
    });
  } catch (error) {
    console.error('Database error:', error);
    throw new Error('Failed to fetch users');
  }
}));

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Endpoint not found',
    path: req.path 
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  const statusCode = error.statusCode || 500;
  const message = process.env.NODE_ENV === 'development' 
    ? error.message 
    : 'Internal server error';

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: error.stack })
  });
});

// Environment validation
const requiredEnvVars = ['PORT', 'NODE_ENV'];
requiredEnvVars.forEach(varName => {
  if (!process.env[varName]) {
    console.error(`Missing required environment variable: ${varName}`);
    process.exit(1);
  }
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);
});

module.exports = app;

